async function foldArchive(chunks, initial, reduce) {
  const iterator = chunks[Symbol.asyncIterator]();
  const decoder = new TextDecoder();

  let state = initial;
  let physicalLine = 0;
  let recordIndex = 0;
  let pending = "";
  let exhausted = false;
  let returned = false;

  const returnIterator = async () => {
    if (returned) return;
    returned = true;

    try {
      const method = iterator.return;
      if (typeof method === "function") {
        await method.call(iterator);
      }
    } catch (_) {}
  };

  const processLine = async (line) => {
    physicalLine++;

    if (line.endsWith("\r")) {
      line = line.slice(0, -1);
    }

    if (line.trim() === "") {
      return false;
    }

    let value;
    try {
      value = JSON.parse(line);
    } catch (_) {
      return false;
    }

    const result = await reduce(state, value, {
      physicalLine,
      recordIndex
    });

    state = result.state;
    recordIndex++;

    return result.done === true;
  };

  const processText = async (text) => {
    let start = 0;

    while (true) {
      const end = text.indexOf("\n", start);

      if (end === -1) {
        pending += text.slice(start);
        return false;
      }

      const line = pending + text.slice(start, end);
      pending = "";
      start = end + 1;

      if (await processLine(line)) {
        return true;
      }
    }
  };

  try {
    while (true) {
      const step = await iterator.next();

      if (step.done) {
        exhausted = true;
        break;
      }

      if (
        await processText(
          decoder.decode(step.value, { stream: true })
        )
      ) {
        await returnIterator();
        return state;
      }
    }

    if (await processText(decoder.decode())) {
      return state;
    }

    if (pending.length !== 0 && (await processLine(pending))) {
      return state;
    }

    return state;
  } catch (error) {
    await returnIterator();
    throw error;
  }
}
